node -e '
const fs = require("fs");
const script = `
import fs from "fs";

async function run() {
  const pagesRes = await fetch("http://localhost:9222/json");
  const pages = await pagesRes.json();
  const page = pages.find(p => p.type === "page");

  const ws = new WebSocket(page.webSocketDebuggerUrl);
  let id = 1;
  const callbacks = new Map();
  ws.addEventListener("message", (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id && callbacks.has(msg.id)) {
      callbacks.get(msg.id)(msg);
      callbacks.delete(msg.id);
    }
  });

  function send(method, params = {}) {
    return new Promise((resolve) => {
      const msgId = id++;
      callbacks.set(msgId, resolve);
      ws.send(JSON.stringify({ id: msgId, method, params }));
    });
  }

  await new Promise((resolve) => ws.addEventListener("open", resolve, { once: true }));

  await send("Page.enable");

  // 1. MOBILE CLOSED (390px)
  await send("Emulation.setDeviceMetricsOverride", {
    width: 390,
    height: 844,
    deviceScaleFactor: 2,
    mobile: true
  });
  await send("Page.navigate", { url: "http://localhost:3000" });
  await new Promise((r) => setTimeout(r, 2000));

  let ss = await send("Page.captureScreenshot", { format: "png" });
  fs.writeFileSync("/tmp/after_390px_menu_closed.png", Buffer.from(ss.result.data, "base64"));
  console.log("Saved /tmp/after_390px_menu_closed.png");

  // 2. OPEN MOBILE MENU
  await send("Runtime.evaluate", {
    expression: "document.querySelector(\x27button[aria-label=\\\x22Open navigation menu\\\x22]\x27).click()"
  });
  await new Promise((r) => setTimeout(r, 600));

  // Inspect DOM rects and styles
  const inspectOpen = await send("Runtime.evaluate", {
    expression: \`(() => {
      const header = document.querySelector("header");
      const menu = document.getElementById("mobile-menu");
      const fab = document.querySelector("a[aria-label*=\x27WhatsApp\x27]");
      const toRect = (r) => r ? { top: r.top, left: r.left, width: r.width, height: r.height } : null;
      return {
        headerBackdrop: header ? getComputedStyle(header).backdropFilter : "none",
        headerRect: toRect(header ? header.getBoundingClientRect() : null),
        menuRect: toRect(menu ? menu.getBoundingClientRect() : null),
        menuBg: menu ? getComputedStyle(menu).backgroundColor : null,
        menuZIndex: menu ? getComputedStyle(menu).zIndex : null,
        fabZIndex: fab ? getComputedStyle(fab).zIndex : null,
        fabRect: toRect(fab ? fab.getBoundingClientRect() : null),
        bodyOverflow: document.body.style.overflow
      };
    })()\`,
    returnByValue: true
  });
  console.log("Mobile Menu Open Inspection:", JSON.stringify(inspectOpen.result.result.value, null, 2));

  ss = await send("Page.captureScreenshot", { format: "png" });
  fs.writeFileSync("/tmp/after_390px_menu_open.png", Buffer.from(ss.result.data, "base64"));
  console.log("Saved /tmp/after_390px_menu_open.png");

  // 3. TEST CLOSE WITH X BUTTON
  await send("Runtime.evaluate", {
    expression: "document.querySelector(\x27button[aria-label=\\\x22Close navigation menu\\\x22]\x27).click()"
  });
  await new Promise((r) => setTimeout(r, 400));
  const afterX = await send("Runtime.evaluate", {
    expression: \`(() => ({
      menuExists: !!document.getElementById("mobile-menu"),
      bodyOverflow: document.body.style.overflow
    }))()\`,
    returnByValue: true
  });
  console.log("After clicking X button:", afterX.result.result.value);

  // 4. TEST CLOSE WITH ESCAPE
  await send("Runtime.evaluate", {
    expression: "document.querySelector(\x27button[aria-label=\\\x22Open navigation menu\\\x22]\x27).click()"
  });
  await new Promise((r) => setTimeout(r, 400));
  await send("Input.dispatchKeyEvent", {
    type: "keyDown",
    key: "Escape",
    code: "Escape",
    windowsVirtualKeyCode: 27
  });
  await send("Input.dispatchKeyEvent", {
    type: "keyUp",
    key: "Escape",
    code: "Escape",
    windowsVirtualKeyCode: 27
  });
  await new Promise((r) => setTimeout(r, 400));
  const afterEscape = await send("Runtime.evaluate", {
    expression: \`(() => ({
      menuExists: !!document.getElementById("mobile-menu"),
      bodyOverflow: document.body.style.overflow
    }))()\`,
    returnByValue: true
  });
  console.log("After Escape key:", afterEscape.result.result.value);

  // 5. TEST CLOSE WHEN LINK IS TAPPED
  await send("Runtime.evaluate", {
    expression: "document.querySelector(\x27button[aria-label=\\\x22Open navigation menu\\\x22]\x27).click()"
  });
  await new Promise((r) => setTimeout(r, 400));
  // Click on "MENU" link
  await send("Runtime.evaluate", {
    expression: \`(() => {
      const links = Array.from(document.querySelectorAll("#mobile-menu a"));
      const menuLink = links.find(a => a.textContent.trim().toUpperCase() === "MENU");
      if (menuLink) { menuLink.click(); return "menu link clicked"; }
      return "link not found";
    })()\`
  });
  await new Promise((r) => setTimeout(r, 1000));
  const afterLink = await send("Runtime.evaluate", {
    expression: \`(() => ({
      currentUrl: window.location.pathname,
      menuExists: !!document.getElementById("mobile-menu"),
      bodyOverflow: document.body.style.overflow
    }))()\`,
    returnByValue: true
  });
  console.log("After tapping link:", afterLink.result.result.value);

  // Navigate back to home
  await send("Page.navigate", { url: "http://localhost:3000" });
  await new Promise((r) => setTimeout(r, 1500));

  // 6. DESKTOP VIEWPORT (1280px)
  await send("Emulation.setDeviceMetricsOverride", {
    width: 1280,
    height: 800,
    deviceScaleFactor: 2,
    mobile: false
  });
  await new Promise((r) => setTimeout(r, 1000));
  ss = await send("Page.captureScreenshot", { format: "png" });
  fs.writeFileSync("/tmp/desktop_1280px.png", Buffer.from(ss.result.data, "base64"));
  console.log("Saved /tmp/desktop_1280px.png");

  const desktopInspect = await send("Runtime.evaluate", {
    expression: \`(() => {
      const desktopNav = document.querySelector("header nav ul");
      const mobileBtn = document.querySelector("button[aria-label=\\\x22Open navigation menu\\\x22]");
      return {
        desktopNavVisible: desktopNav ? getComputedStyle(desktopNav).display !== "none" : false,
        mobileBtnHidden: mobileBtn ? getComputedStyle(mobileBtn).display === "none" : true
      };
    })()\`,
    returnByValue: true
  });
  console.log("Desktop inspection:", desktopInspect.result.result.value);

  ws.close();
}
run().catch(console.error);
`;
fs.writeFileSync("/tmp/verify.mjs", script);
'

